from pathlib import Path


def replace_once(text: str, old: str, new: str, label: str) -> str:
    if old not in text:
        raise SystemExit(f'Anchor not found: {label}')
    return text.replace(old, new, 1)

# simulation/types.ts
types_path = Path('src/simulation/types.ts')
types = types_path.read_text()
types = replace_once(types, "  shuntFraction: number\n  compliance: number\n", "  shuntFraction: number\n  maxSpO2: number\n  compliance: number\n", 'PatientSettings maxSpO2')
types_path.write_text(types)

# simulation/engine.ts
engine_path = Path('src/simulation/engine.ts')
engine = engine_path.read_text()
old_model = """function directSpO2FromAlveolarFraction(alveolarFraction: number, ventilator: VentilatorSettings, patient: PatientSettings): number {\n  // Keep oxygenation independent from airway mechanics: shunt is an explicit\n  // patient property. Obstruction retains a small V/Q-mismatch penalty, while\n  // PEEP can recruit a fraction of shunt only when the lung is relatively\n  // non-compliant.\n  const obstructionPenalty = clamp((patient.expiratoryResistance - 8) / 32, 0, 1) * 0.018\n  const effectiveFraction = clamp(alveolarFraction - obstructionPenalty, 0.01, 0.95)\n\n  // Convert the alveolar oxygen reservoir to an approximate end-capillary PO2\n  // and then to haemoglobin saturation. The previous model mixed saturations\n  // directly, which created an artificial hard SpO2 ceiling in large shunts: a\n  // rise from 35% to 100% FiO2 could become invisible once the ventilated blood\n  // was already near 100% saturation. Mixing oxygen content retains the limited\n  // response of true shunt while allowing hyperoxia in ventilated units to make\n  // an appropriate, modest contribution after blood streams mix.\n  const endCapillaryPo2 = clamp(effectiveFraction * 650, 20, 650)\n  const ventilatedSaturation = clamp(saturationFromOxygenTension(endCapillaryPo2), 50, 100)\n\n  const baselineShunt = clamp(patient.shuntFraction ?? 0.03, 0, 0.5)\n  const recruitability = clamp((60 - patient.compliance) / 45, 0, 1)\n  const peepRecruitment = 0.55 * recruitability * clamp((ventilator.peep - 5) / 10, 0, 1)\n  const effectiveShunt = baselineShunt * (1 - peepRecruitment)\n\n  const haemoglobin = 15\n  const oxygenCapacity = 1.34 * haemoglobin\n  const ventilatedContent = oxygenCapacity * (ventilatedSaturation / 100) + 0.003 * endCapillaryPo2\n  const venousLikeSaturation = 75\n  const venousLikePo2 = 40\n  const venousContent = oxygenCapacity * (venousLikeSaturation / 100) + 0.003 * venousLikePo2\n  const mixedContent = ventilatedContent * (1 - effectiveShunt) + venousContent * effectiveShunt\n\n  // Invert the content relationship numerically to obtain an equivalent mixed\n  // arterial saturation for the pulse-oximeter model.\n  let low = 50\n  let high = 100\n  for (let iteration = 0; iteration < 24; iteration += 1) {\n    const mid = (low + high) / 2\n    if (oxygenContentForSaturation(mid) < mixedContent) low = mid\n    else high = mid\n  }\n  return clamp((low + high) / 2, 50, 100)\n}\n"""
new_model = """function directSpO2FromAlveolarFraction(alveolarFraction: number, ventilator: VentilatorSettings, patient: PatientSettings): number {\n  // Keep oxygenation independent from airway mechanics: shunt is an explicit\n  // patient property. Obstruction retains a small V/Q-mismatch penalty, while\n  // PEEP can recruit a fraction of shunt only when the lung is relatively\n  // non-compliant.\n  const obstructionPenalty = clamp((patient.expiratoryResistance - 8) / 32, 0, 1) * 0.018\n  const effectiveFraction = clamp(alveolarFraction - obstructionPenalty, 0.01, 0.95)\n\n  // Convert the alveolar oxygen reservoir to an approximate end-capillary PO2\n  // and oxygen content. The shunt model then uses a Fick-style oxygen-content\n  // balance rather than mixing fixed saturations. This matters when VO2 rises:\n  // greater systemic extraction lowers mixed-venous oxygen content, so the same\n  // shunt fraction produces a larger arterial oxygen-content penalty.\n  const endCapillaryPo2 = clamp(effectiveFraction * 650, 20, 650)\n  const ventilatedSaturation = clamp(saturationFromOxygenTension(endCapillaryPo2), 50, 100)\n\n  const baselineShunt = clamp(patient.shuntFraction ?? 0.03, 0, 0.5)\n  const recruitability = clamp((60 - patient.compliance) / 45, 0, 1)\n  const peepRecruitment = 0.55 * recruitability * clamp((ventilator.peep - 5) / 10, 0, 1)\n  const effectiveShunt = baselineShunt * (1 - peepRecruitment)\n\n  const haemoglobin = 15\n  const oxygenCapacity = 1.34 * haemoglobin\n  const ventilatedContent = oxygenCapacity * (ventilatedSaturation / 100) + 0.003 * endCapillaryPo2\n\n  // EDUVENT does not yet have a cardiovascular model, so use a teaching\n  // reference cardiac output of 5 L/min. At VO2 250 mL/min this yields the\n  // familiar ~5 mL/dL arteriovenous oxygen-content difference. Combining the\n  // classic shunt equation with Fick gives:\n  // CaO2 = CcO2 - Qs/(Qt-Qs) * (VO2/CO).\n  const referenceCardiacOutputLMin = 5\n  const oxygenExtractionMlDl = Math.max(patient.oxygenConsumption ?? 250, 0) / referenceCardiacOutputLMin / 10\n  const shuntContentPenalty = effectiveShunt >= 0.999\n    ? ventilatedContent\n    : (effectiveShunt / Math.max(1 - effectiveShunt, 0.001)) * oxygenExtractionMlDl\n  const arterialContent = clamp(ventilatedContent - shuntContentPenalty, oxygenContentForSaturation(50), ventilatedContent)\n\n  // Invert oxygen content numerically to obtain the equivalent arterial\n  // saturation, then apply the optional instructor-set SpO2 ceiling. The ceiling\n  // is a scenario control, not part of the shunt calculation itself.\n  let low = 50\n  let high = 100\n  for (let iteration = 0; iteration < 24; iteration += 1) {\n    const mid = (low + high) / 2\n    if (oxygenContentForSaturation(mid) < arterialContent) low = mid\n    else high = mid\n  }\n  const physiologicalSaturation = clamp((low + high) / 2, 50, 100)\n  const maxSpO2 = clamp(patient.maxSpO2 ?? 100, 80, 100)\n  return Math.min(physiologicalSaturation, maxSpO2)\n}\n"""
engine = replace_once(engine, old_model, new_model, 'Fick shunt model')
engine_path.write_text(engine)

# App.tsx
app_path = Path('src/App.tsx')
app = app_path.read_text()
app = replace_once(app, "  sex: 'male', heightCm: 170, oxygenConsumption: 250, frc: 2500, shuntFraction: 0.03,\n", "  sex: 'male', heightCm: 170, oxygenConsumption: 250, frc: 2500, shuntFraction: 0.03, maxSpO2: 100,\n", 'initial maxSpO2')
app = replace_once(app, "    shuntFraction: lerp(from.shuntFraction ?? 0.03, to.shuntFraction ?? 0.03),\n    compliance: lerp(from.compliance, to.compliance),\n", "    shuntFraction: lerp(from.shuntFraction ?? 0.03, to.shuntFraction ?? 0.03),\n    maxSpO2: lerp(from.maxSpO2 ?? 100, to.maxSpO2 ?? 100),\n    compliance: lerp(from.compliance, to.compliance),\n", 'interpolate maxSpO2')
app = replace_once(app, "                        <em>{alarmLimits.pressureLimit}</em>\n                        <input className=\"vertical-alarm-slider\" type=\"range\" min=\"0\" max={alarmLimits.pressureLimit} step=\"1\" value={alarmLimits.peakPressure} onChange={(event) => setAlarmLimits((current) => ({ ...current, peakPressure: Math.min(Number(event.target.value), current.pressureLimit) }))} />\n", "                        <em>60</em>\n                        <input className=\"vertical-alarm-slider\" type=\"range\" min=\"0\" max=\"60\" step=\"1\" value={alarmLimits.peakPressure} onChange={(event) => setAlarmLimits((current) => ({ ...current, peakPressure: Math.min(Number(event.target.value), current.pressureLimit) }))} />\n", 'fixed peak pressure slider scale')
app = replace_once(app, "  const resetVentilator = () => setVentilator({ ...initialVentilator })\n  const resetPatient = () => setPatient({ ...initialPatient })\n", "  const resetVentilator = () => setVentilator({ ...initialVentilator })\n  const resetPatientRespiratory = () => setPatient((current) => ({\n    ...current,\n    compliance: initialPatient.compliance,\n    resistance: initialPatient.resistance,\n    expiratoryResistance: initialPatient.expiratoryResistance,\n    spontaneousRate: initialPatient.spontaneousRate,\n    effort: initialPatient.effort,\n    neuralInspiratoryTime: initialPatient.neuralInspiratoryTime,\n    effortRisePercent: initialPatient.effortRisePercent,\n    effortRelaxationPercent: initialPatient.effortRelaxationPercent,\n    endExpiratoryOesophagealPressure: initialPatient.endExpiratoryOesophagealPressure,\n  }))\n  const resetPatientPhysiology = () => setPatient((current) => ({\n    ...current,\n    sex: initialPatient.sex,\n    heightCm: initialPatient.heightCm,\n    oxygenConsumption: initialPatient.oxygenConsumption,\n    frc: initialPatient.frc,\n    shuntFraction: initialPatient.shuntFraction,\n    maxSpO2: initialPatient.maxSpO2,\n    co2Production: initialPatient.co2Production,\n    deadSpaceVolume: initialPatient.deadSpaceVolume,\n  }))\n", 'split patient resets')
app = app.replace("appVersion: '0.77.2'", "appVersion: '0.77.3'", 1)
app = app.replace('<span className="version">v0.77.2</span>', '<span className="version">v0.77.3</span>', 1)
app = replace_once(app, "            <PatientControls settings={patient} onChange={setPatient} onReset={resetPatient} transitionSeconds={patientTransitionSeconds} onTransitionSecondsChange={setPatientTransitionSeconds} showPatientEffort={patientEffortVisible} onShowPatientEffortChange={teachingSession.role === 'candidate' ? () => undefined : setShowPatientEffort} patientEffortLocked={teachingSession.role === 'candidate'} />\n", "            <PatientControls settings={patient} onChange={setPatient} onReset={resetPatientRespiratory} onResetPhysiology={resetPatientPhysiology} transitionSeconds={patientTransitionSeconds} onTransitionSecondsChange={setPatientTransitionSeconds} showPatientEffort={patientEffortVisible} onShowPatientEffortChange={teachingSession.role === 'candidate' ? () => undefined : setShowPatientEffort} patientEffortLocked={teachingSession.role === 'candidate'} showSpO2Ceiling={teachingSession.role !== 'candidate'} />\n", 'PatientControls reset props')
app_path.write_text(app)

# Controls.tsx
controls_path = Path('src/components/Controls.tsx')
controls = controls_path.read_text()
controls = replace_once(controls, "export function PatientControls({ settings, onChange, onReset, transitionSeconds, onTransitionSecondsChange, showPatientEffort, onShowPatientEffortChange, patientEffortLocked = false }: { settings: PatientSettings; onChange: (next: PatientSettings) => void; onReset: () => void; transitionSeconds: number; onTransitionSecondsChange: (seconds: number) => void; showPatientEffort: boolean; onShowPatientEffortChange: (value: boolean) => void; patientEffortLocked?: boolean }) {", "export function PatientControls({ settings, onChange, onReset, onResetPhysiology, transitionSeconds, onTransitionSecondsChange, showPatientEffort, onShowPatientEffortChange, patientEffortLocked = false, showSpO2Ceiling = true }: { settings: PatientSettings; onChange: (next: PatientSettings) => void; onReset: () => void; onResetPhysiology: () => void; transitionSeconds: number; onTransitionSecondsChange: (seconds: number) => void; showPatientEffort: boolean; onShowPatientEffortChange: (value: boolean) => void; patientEffortLocked?: boolean; showSpO2Ceiling?: boolean }) {", 'PatientControls signature')
controls = replace_once(controls, """  const presets: Record<string, Partial<PatientSettings>> = {\n    Normal: { shuntFraction: 0.03, compliance: 60, resistance: 6, expiratoryResistance: 8, spontaneousRate: 12, effort: 5, neuralInspiratoryTime: 1, effortRisePercent: 50, effortRelaxationPercent: 50 },\n    ARDS: { shuntFraction: 0.25, compliance: 25, resistance: 8, expiratoryResistance: 10, spontaneousRate: 25, effort: 10, neuralInspiratoryTime: 0.8, effortRisePercent: 20, effortRelaxationPercent: 25 },\n    COPD: { shuntFraction: 0.05, compliance: 80, resistance: 16, expiratoryResistance: 28, spontaneousRate: 18, effort: 8, neuralInspiratoryTime: 0.9, effortRisePercent: 30, effortRelaxationPercent: 40 },\n    Asthma: { shuntFraction: 0.04, compliance: 70, resistance: 25, expiratoryResistance: 40, spontaneousRate: 24, effort: 11, neuralInspiratoryTime: 0.8, effortRisePercent: 20, effortRelaxationPercent: 30 },\n  }\n""", """  const normalPhysiology = { sex: 'male' as const, heightCm: 170, oxygenConsumption: 250, frc: 2500, maxSpO2: 100, co2Production: 250, deadSpaceVolume: 150 }\n  const presets: Record<string, PatientSettings> = {\n    Normal: { ...normalPhysiology, shuntFraction: 0.03, compliance: 60, resistance: 6, expiratoryResistance: 8, spontaneousRate: 12, effort: 5, neuralInspiratoryTime: 1, effortRisePercent: 50, effortRelaxationPercent: 50, endExpiratoryOesophagealPressure: -5 },\n    ARDS: { ...normalPhysiology, shuntFraction: 0.25, compliance: 25, resistance: 8, expiratoryResistance: 10, spontaneousRate: 25, effort: 10, neuralInspiratoryTime: 0.8, effortRisePercent: 20, effortRelaxationPercent: 25, endExpiratoryOesophagealPressure: -5 },\n    COPD: { ...normalPhysiology, shuntFraction: 0.05, compliance: 80, resistance: 16, expiratoryResistance: 28, spontaneousRate: 18, effort: 8, neuralInspiratoryTime: 0.9, effortRisePercent: 30, effortRelaxationPercent: 40, endExpiratoryOesophagealPressure: -5 },\n    Asthma: { ...normalPhysiology, shuntFraction: 0.04, compliance: 70, resistance: 25, expiratoryResistance: 40, spontaneousRate: 24, effort: 11, neuralInspiratoryTime: 0.8, effortRisePercent: 20, effortRelaxationPercent: 30, endExpiratoryOesophagealPressure: -5 },\n  }\n""", 'full patient presets')
controls = replace_once(controls, '<button className="reset-settings-button patient-reset-button" type="button" onClick={onReset}>Reset patient</button>', '<button className="reset-settings-button patient-reset-button" type="button" onClick={onReset}>Reset respiratory</button>', 'respiratory reset label')
controls = replace_once(controls, '<div className="preset-row">{Object.keys(presets).map((name) => <button key={name} onClick={() => patch(presets[name])}>{name}</button>)}</div>', '<div className="preset-row">{Object.keys(presets).map((name) => <button key={name} onClick={() => onChange({ ...presets[name] })}>{name}</button>)}</div>', 'preset full reset action')
controls = replace_once(controls, '      <div className="patient-subsection-title">Physiological</div>\n', '      <div className="patient-subsection-heading">\n        <div className="patient-subsection-title">Physiological</div>\n        <button className="reset-settings-button patient-reset-button" type="button" onClick={onResetPhysiology}>Reset physiological</button>\n      </div>\n', 'physiology reset button')
controls = replace_once(controls, '      <Slider label="Shunt" value={Math.round((settings.shuntFraction ?? 0.03) * 100)} unit="%" min={0} max={50} step={1} onChange={(v) => patch({ shuntFraction: v / 100 })} />\n', '      <Slider label="Shunt" value={Math.round((settings.shuntFraction ?? 0.03) * 100)} unit="%" min={0} max={50} step={1} onChange={(v) => patch({ shuntFraction: v / 100 })} />\n      {showSpO2Ceiling && <Slider label="Maximum SpO₂" value={Math.round(settings.maxSpO2 ?? 100)} unit="%" min={80} max={100} step={1} onChange={(v) => patch({ maxSpO2: v })} />}\n', 'maximum SpO2 slider')
controls_path.write_text(controls)

# styles.css
